from pysat.solvers import Glucose4
import itertools

def solve_graceful_sat(C):
    V = 3
    N = C * V
    E = C * 3 + (C - 1) * 3

    edges = []
    for g in range(C):
        base = g * V
        edges.append((base, base + 1))
        edges.append((base + 1, base + 2))
        edges.append((base, base + 2))

    for g in range(C - 1):
        base1 = g * V
        base2 = (g + 1) * V
        for i in range(V):
            edges.append((base1 + i, base2 + i))

    # Variables:
    # x[u][l] = 1 if vertex u has label l
    # y[e][d] = 1 if edge e has difference d

    def x(u, l):
        return u * (E + 1) + l + 1

    def y(e, d):
        return N * (E + 1) + e * E + d

    solver = Glucose4()

    # Each vertex has exactly one label
    for u in range(N):
        solver.add_clause([x(u, l) for l in range(E + 1)])
        for l1 in range(E + 1):
            for l2 in range(l1 + 1, E + 1):
                solver.add_clause([-x(u, l1), -x(u, l2)])

    # Each label is used at most once
    for l in range(E + 1):
        for u1 in range(N):
            for u2 in range(u1 + 1, N):
                solver.add_clause([-x(u1, l), -x(u2, l)])

    # Each edge has exactly one difference
    for e in range(E):
        solver.add_clause([y(e, d) for d in range(1, E + 1)])
        for d1 in range(1, E + 1):
            for d2 in range(d1 + 1, E + 1):
                solver.add_clause([-y(e, d1), -y(e, d2)])

    # Each difference is used at most once
    for d in range(1, E + 1):
        for e1 in range(E):
            for e2 in range(e1 + 1, E):
                solver.add_clause([-y(e1, d), -y(e2, d)])

    # Link x and y
    for e_idx, (u, v) in enumerate(edges):
        for l1 in range(E + 1):
            for l2 in range(E + 1):
                if l1 != l2:
                    d = abs(l1 - l2)
                    # if x[u][l1] and x[v][l2] then y[e_idx][d]
                    solver.add_clause([-x(u, l1), -x(v, l2), y(e_idx, d)])
                else:
                    solver.add_clause([-x(u, l1), -x(v, l2)])

    # Symmetry breaking
    # labels[0] < labels[1] < labels[2]
    for l1 in range(E + 1):
        for l2 in range(l1 + 1):
            solver.add_clause([-x(0, l1), -x(1, l2)])
            solver.add_clause([-x(1, l1), -x(2, l2)])
            solver.add_clause([-x(0, l1), -x(2, l2)])

    # labels[0] <= E // 2
    for l in range(E // 2 + 1, E + 1):
        solver.add_clause([-x(0, l)])

    print(f"Solving C={C}...")
    if solver.solve():
        model = solver.get_model()
        labels = [-1] * N
        for u in range(N):
            for l in range(E + 1):
                if model[x(u, l) - 1] > 0:
                    labels[u] = l
        print(f"SAT: {labels}")
        return True
    else:
        print("UNSAT")
        return False

