    for g in range(C - 1):
        base1 = g * V
        base2 = (g + 1) * V
        for i in range(V):
            edges.append((base1 + i, base2 + i))

    def x(u, l):
        return u * (E + 1) + l + 1

    def y(e, d):
        return N * (E + 1) + e * E + d

    solver = Glucose4()

    for u in range(N):
        solver.add_clause([x(u, l) for l in range(E + 1)])
        for l1 in range(E + 1):
            for l2 in range(l1 + 1, E + 1):
                solver.add_clause([-x(u, l1), -x(u, l2)])

    for l in range(E + 1):
        for u1 in range(N):
            for u2 in range(u1 + 1, N):
                solver.add_clause([-x(u1, l), -x(u2, l)])

    for e in range(E):
        solver.add_clause([y(e, d) for d in range(1, E + 1)])
        for d1 in range(1, E + 1):
            for d2 in range(d1 + 1, E + 1):
                solver.add_clause([-y(e, d1), -y(e, d2)])

    for d in range(1, E + 1):
        for e1 in range(E):
            for e2 in range(e1 + 1, E):
                solver.add_clause([-y(e1, d), -y(e2, d)])

    for e_idx, (u, v) in enumerate(edges):
        for l1 in range(E + 1):
            for l2 in range(E + 1):
                if l1 != l2:
                    d = abs(l1 - l2)
                    solver.add_clause([-x(u, l1), -x(v, l2), y(e_idx, d)])
                else:
                    solver.add_clause([-x(u, l1), -x(v, l2)])

    # Symmetry breaking
    for l1 in range(E + 1):
        for l2 in range(l1 + 1):
            solver.add_clause([-x(0, l1), -x(1, l2)])
            solver.add_clause([-x(1, l1), -x(2, l2)])
            solver.add_clause([-x(0, l1), -x(2, l2)])

    for l in range(E // 2 + 1, E + 1):
        solver.add_clause([-x(0, l)])

    print(f"Solving C={C}...")
    if solver.solve():
        model = solver.get_model()
        labels = [-1] * N
        for u in range(N):
            for l in range(E + 1):
                if model[x(u, l) - 1] > 0:
                    labels[u] = l
        print(f"SAT: {labels}")
        return labels
    else:
        print("UNSAT")
        return None

